#[component]
pub fn Icon(name: String, #[props(default = 20)] size: u32) -> Element {
    let svg = format!(
        "<svg viewBox=\"0 0 24 24\" width=\"{size}\" height=\"{size}\" aria-hidden=\"true\"><path fill=\"currentColor\" d=\"{}\"/></svg>",
        path(&name)
    );
    rsx! {
        span { class: "icon", dangerous_inner_html: "{svg}" }
    }
}

/// Логотип-планета с кольцом; цвета берутся из темы.
pub const LOGO_SVG: &str = r##"<svg viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id="nl-g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="var(--accent)"/><stop offset="1" stop-color="var(--accent2)"/></linearGradient><radialGradient id="nl-s" cx=".35" cy=".3" r=".8"><stop offset="0" stop-color="#fff" stop-opacity=".55"/><stop offset=".5" stop-color="#fff" stop-opacity="0"/></radialGradient></defs><ellipse cx="32" cy="34" rx="29" ry="9" fill="none" stroke="url(#nl-g)" stroke-width="3" opacity=".45" transform="rotate(-18 32 34)"/><circle cx="32" cy="32" r="15" fill="url(#nl-g)"/><circle cx="32" cy="32" r="15" fill="url(#nl-s)"/><path d="M5 40.5c8 6 46-6 54-18" fill="none" stroke="url(#nl-g)" stroke-width="3" stroke-linecap="round" transform="rotate(-18 32 34)"/><circle cx="52" cy="12" r="1.6" fill="#fff"/><circle cx="10" cy="18" r="1" fill="#fff" opacity=".7"/></svg>"##;

/// Логотип для заставки: те же формы, но каждая часть анимируется отдельно —
/// кольцо прорисовывается (`pathLength` = 1), планета «выпрыгивает», звёзды мерцают.
pub const INTRO_SVG: &str = r##"<svg class="intro-svg" viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id="ni-g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="var(--accent)"/><stop offset="1" stop-color="var(--accent2)"/></linearGradient><radialGradient id="ni-s" cx=".35" cy=".3" r=".8"><stop offset="0" stop-color="#fff" stop-opacity=".55"/><stop offset=".5" stop-color="#fff" stop-opacity="0"/></radialGradient></defs><g transform="rotate(-18 32 34)"><ellipse class="i-ring" pathLength="1" cx="32" cy="34" rx="29" ry="9" fill="none" stroke="url(#ni-g)" stroke-width="3"/></g><g class="i-planet"><circle cx="32" cy="32" r="15" fill="url(#ni-g)"/><circle class="i-shine" cx="32" cy="32" r="15" fill="url(#ni-s)"/></g><g transform="rotate(-18 32 34)"><path class="i-arc" pathLength="1" d="M5 40.5c8 6 46-6 54-18" fill="none" stroke="url(#ni-g)" stroke-width="3" stroke-linecap="round"/></g><circle class="i-star s1" cx="52" cy="12" r="1.6" fill="#fff"/><circle class="i-star s2" cx="10" cy="18" r="1" fill="#fff"/></svg>"##;
